  const upload = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!selected) return; setBusy(true); const form = new FormData(event.currentTarget); try { await api.uploadDocument(selected, { documentType: form.get('documentType'), fileName: form.get('fileName'), storageKey: form.get('storageKey'), expiryDate: form.get('expiryDate') || null }); setAdding(false); await choose(selected); } catch (err) { setError(err instanceof Error ? err.message : 'Document could not be added.'); } finally { setBusy(false); } };
